<template>
  <div class="flex items-center gap-2 border rounded-md px-3 h-10 bg-background">
    <TriStateCheckbox :id="propertyName" :model-value="boolToTriState(value)" @update:model-value="onUpdate" />
    <Label :for="propertyName" class="text-sm text-nowrap cursor-pointer">{{ label }}</Label>
  </div>
</template>

<script setup lang="ts">
import TriStateCheckbox from '~/components/common/TriStateCheckbox.vue';

interface Props {
  value: boolean | null | undefined;
  propertyName: string;
  label: string;
  isFirstPageOnly?: boolean;
}

const props = withDefaults(defineProps<Props>(), { isFirstPageOnly: true });

const route = useRoute();

function onUpdate(v: boolean | 'indeterminate') {
  // indeterminate clears the filter, so drop the param entirely instead of writing a value
  const queryValue = v === 'indeterminate' ? undefined : String(v);
  navigateTo({
    query: { ...route.query, [props.propertyName]: queryValue, ...(props.isFirstPageOnly ? { page: 1 } : {}) },
  });
}
</script>
